/*
 * Integrity checks for the xz reimplementation: CRC32 (IEEE 802.3,
 * reflected), CRC64 (ECMA-182, reflected), and SHA-256 (FIPS 180-4),
 * as used by the .xz file format.
 *
 * The CRC tables are generated at runtime on first use. CRC32 uses the
 * reflected polynomial 0xEDB88320 and CRC64 the reflected polynomial
 * 0xC96C5795D7870F42; both use init/xorout of all-ones. In the .xz
 * Check field CRCs are stored as little-endian integers while the
 * SHA-256 digest is stored as raw big-endian bytes.
 */
#include "check.h"

/* ---- Check ID table -------------------------------------------------- */

/*
 * Sizes of the Check field per the .xz spec, indexed by Check ID
 * (0x00-0x0F): IDs 0x00 -> 0, 0x01-0x03 -> 4, 0x04-0x06 -> 8,
 * 0x07-0x09 -> 16, 0x0A-0x0C -> 32, 0x0D-0x0F -> 64.
 */
static const uint8_t check_sizes[CHECK_ID_MAX + 1] = {
	0,			/* 0x00 None */
	4, 4, 4,		/* 0x01 CRC32, 0x02-0x03 reserved */
	8, 8, 8,		/* 0x04 CRC64, 0x05-0x06 reserved */
	16, 16, 16,		/* 0x07-0x09 reserved */
	32, 32, 32,		/* 0x0A SHA-256, 0x0B-0x0C reserved */
	64, 64, 64		/* 0x0D-0x0F reserved */
};

int
check_size_by_id(int id)
{
	if (id < 0 || id > CHECK_ID_MAX)
		return -1;
	return check_sizes[id];
}

bool
check_id_supported(int id)
{
	return id == CHECK_ID_NONE || id == CHECK_ID_CRC32
		|| id == CHECK_ID_CRC64 || id == CHECK_ID_SHA256;
}

/* ---- CRC32 / CRC64 --------------------------------------------------- */

static uint32_t crc32_table[256];
static uint64_t crc64_table[256];
static bool crc_tables_ready = false;

static void
crc_tables_init(void)
{
	if (crc_tables_ready)
		return;

	for (uint32_t i = 0; i < 256; i++) {
		uint32_t c32 = i;
		uint64_t c64 = i;
		for (int j = 0; j < 8; j++) {
			c32 = (c32 >> 1)
				^ ((c32 & 1) ? UINT32_C(0xEDB88320) : 0);
			c64 = (c64 >> 1)
				^ ((c64 & 1)
					? UINT64_C(0xC96C5795D7870F42) : 0);
		}
		crc32_table[i] = c32;
		crc64_table[i] = c64;
	}

	crc_tables_ready = true;
}

uint32_t
my_crc32(const uint8_t *buf, size_t len, uint32_t crc)
{
	crc_tables_init();

	crc = ~crc;
	for (size_t i = 0; i < len; i++)
		crc = crc32_table[(crc ^ buf[i]) & 0xFF] ^ (crc >> 8);
	return ~crc;
}

uint64_t
my_crc64(const uint8_t *buf, size_t len, uint64_t crc)
{
	crc_tables_init();

	crc = ~crc;
	for (size_t i = 0; i < len; i++)
		crc = crc64_table[(crc ^ buf[i]) & 0xFF] ^ (crc >> 8);
	return ~crc;
}

/* ---- SHA-256 (FIPS 180-4) -------------------------------------------- */

/* Round constants: first 32 bits of the fractional parts of the cube
 * roots of the first 64 primes. */
static const uint32_t sha256_k[64] = {
	UINT32_C(0x428A2F98), UINT32_C(0x71374491),
	UINT32_C(0xB5C0FBCF), UINT32_C(0xE9B5DBA5),
	UINT32_C(0x3956C25B), UINT32_C(0x59F111F1),
	UINT32_C(0x923F82A4), UINT32_C(0xAB1C5ED5),
	UINT32_C(0xD807AA98), UINT32_C(0x12835B01),
	UINT32_C(0x243185BE), UINT32_C(0x550C7DC3),
	UINT32_C(0x72BE5D74), UINT32_C(0x80DEB1FE),
	UINT32_C(0x9BDC06A7), UINT32_C(0xC19BF174),
	UINT32_C(0xE49B69C1), UINT32_C(0xEFBE4786),
	UINT32_C(0x0FC19DC6), UINT32_C(0x240CA1CC),
	UINT32_C(0x2DE92C6F), UINT32_C(0x4A7484AA),
	UINT32_C(0x5CB0A9DC), UINT32_C(0x76F988DA),
	UINT32_C(0x983E5152), UINT32_C(0xA831C66D),
	UINT32_C(0xB00327C8), UINT32_C(0xBF597FC7),
	UINT32_C(0xC6E00BF3), UINT32_C(0xD5A79147),
	UINT32_C(0x06CA6351), UINT32_C(0x14292967),
	UINT32_C(0x27B70A85), UINT32_C(0x2E1B2138),
	UINT32_C(0x4D2C6DFC), UINT32_C(0x53380D13),
	UINT32_C(0x650A7354), UINT32_C(0x766A0ABB),
	UINT32_C(0x81C2C92E), UINT32_C(0x92722C85),
	UINT32_C(0xA2BFE8A1), UINT32_C(0xA81A664B),
	UINT32_C(0xC24B8B70), UINT32_C(0xC76C51A3),
	UINT32_C(0xD192E819), UINT32_C(0xD6990624),
	UINT32_C(0xF40E3585), UINT32_C(0x106AA070),
	UINT32_C(0x19A4C116), UINT32_C(0x1E376C08),
	UINT32_C(0x2748774C), UINT32_C(0x34B0BCB5),
	UINT32_C(0x391C0CB3), UINT32_C(0x4ED8AA4A),
	UINT32_C(0x5B9CCA4F), UINT32_C(0x682E6FF3),
	UINT32_C(0x748F82EE), UINT32_C(0x78A5636F),
	UINT32_C(0x84C87814), UINT32_C(0x8CC70208),
	UINT32_C(0x90BEFFFA), UINT32_C(0xA4506CEB),
	UINT32_C(0xBEF9A3F7), UINT32_C(0xC67178F2)
};

static uint32_t
rotr32(uint32_t x, unsigned n)
{
	return (x >> n) | (x << (32 - n));
}

static void
sha256_compress(uint32_t state[8], const uint8_t block[64])
{
	uint32_t w[64];
	uint32_t a, b, c, d, e, f, g, h;

	for (int i = 0; i < 16; i++) {
		w[i] = ((uint32_t)block[i * 4] << 24)
			| ((uint32_t)block[i * 4 + 1] << 16)
			| ((uint32_t)block[i * 4 + 2] << 8)
			| (uint32_t)block[i * 4 + 3];
	}
	for (int i = 16; i < 64; i++) {
		uint32_t s0 = rotr32(w[i - 15], 7) ^ rotr32(w[i - 15], 18)
			^ (w[i - 15] >> 3);
		uint32_t s1 = rotr32(w[i - 2], 17) ^ rotr32(w[i - 2], 19)
			^ (w[i - 2] >> 10);
		w[i] = w[i - 16] + s0 + w[i - 7] + s1;
	}

	a = state[0];
	b = state[1];
	c = state[2];
	d = state[3];
	e = state[4];
	f = state[5];
	g = state[6];
	h = state[7];

	for (int i = 0; i < 64; i++) {
		uint32_t s1 = rotr32(e, 6) ^ rotr32(e, 11) ^ rotr32(e, 25);
		uint32_t ch = (e & f) ^ (~e & g);
		uint32_t t1 = h + s1 + ch + sha256_k[i] + w[i];
		uint32_t s0 = rotr32(a, 2) ^ rotr32(a, 13) ^ rotr32(a, 22);
		uint32_t maj = (a & b) ^ (a & c) ^ (b & c);
		uint32_t t2 = s0 + maj;

		h = g;
		g = f;
		f = e;
		e = d + t1;
		d = c;
		c = b;
		b = a;
		a = t1 + t2;
	}

	state[0] += a;
	state[1] += b;
	state[2] += c;
	state[3] += d;
	state[4] += e;
	state[5] += f;
	state[6] += g;
	state[7] += h;
}

void
my_sha256(const uint8_t *buf, size_t len, uint8_t out[32])
{
	/* Initial hash values: first 32 bits of the fractional parts of
	 * the square roots of the first 8 primes. */
	uint32_t state[8] = {
		UINT32_C(0x6A09E667), UINT32_C(0xBB67AE85),
		UINT32_C(0x3C6EF372), UINT32_C(0xA54FF53A),
		UINT32_C(0x510E527F), UINT32_C(0x9B05688C),
		UINT32_C(0x1F83D9AB), UINT32_C(0x5BE0CD19)
	};
	uint8_t tail[128];
	size_t full = len / 64;
	size_t rem = len % 64;

	for (size_t i = 0; i < full; i++)
		sha256_compress(state, buf + i * 64);

	/* Padding: 0x80, zeros, then the 64-bit big-endian bit length,
	 * using one or two final blocks as needed. */
	uint64_t bitlen = (uint64_t)len * 8;
	size_t tail_len = (rem < 56) ? 64 : 128;

	for (size_t i = 0; i < rem; i++)
		tail[i] = buf[full * 64 + i];
	tail[rem] = 0x80;
	for (size_t i = rem + 1; i < tail_len - 8; i++)
		tail[i] = 0x00;
	for (int i = 0; i < 8; i++)
		tail[tail_len - 1 - i] = (uint8_t)(bitlen >> (i * 8));

	sha256_compress(state, tail);
	if (tail_len == 128)
		sha256_compress(state, tail + 64);

	for (int i = 0; i < 8; i++) {
		out[i * 4] = (uint8_t)(state[i] >> 24);
		out[i * 4 + 1] = (uint8_t)(state[i] >> 16);
		out[i * 4 + 2] = (uint8_t)(state[i] >> 8);
		out[i * 4 + 3] = (uint8_t)state[i];
	}
}

/* ---- Generic dispatch ------------------------------------------------ */

void
check_compute(int id, const uint8_t *buf, size_t len, uint8_t *out)
{
	switch (id) {
	case CHECK_ID_NONE:
		break;

	case CHECK_ID_CRC32: {
		uint32_t crc = my_crc32(buf, len, 0);
		out[0] = (uint8_t)crc;
		out[1] = (uint8_t)(crc >> 8);
		out[2] = (uint8_t)(crc >> 16);
		out[3] = (uint8_t)(crc >> 24);
		break;
	}

	case CHECK_ID_CRC64: {
		uint64_t crc = my_crc64(buf, len, 0);
		for (int i = 0; i < 8; i++)
			out[i] = (uint8_t)(crc >> (i * 8));
		break;
	}

	case CHECK_ID_SHA256:
		my_sha256(buf, len, out);
		break;

	default:
		break;
	}
}

/*
 * Standalone tests for /workspace/src/check.c:
 *  - CRC32 / CRC64 against standard check vectors
 *  - SHA-256 against FIPS 180-4 vectors (incl. padding boundaries)
 *  - check_size_by_id / check_id_supported
 *  - check_compute byte order (LE for CRCs, BE digest for SHA-256)
 */
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include "check.h"

static int failures = 0;

static void
hex(const uint8_t *p, size_t n, char *s)
{
	for (size_t i = 0; i < n; i++)
		sprintf(s + i * 2, "%02x", p[i]);
}

static void
expect_u32(const char *name, uint32_t got, uint32_t want)
{
	if (got != want) {
		printf("FAIL %s: got 0x%08X want 0x%08X\n", name, got, want);
		failures++;
	} else {
		printf("ok   %s = 0x%08X\n", name, got);
	}
}

static void
expect_u64(const char *name, uint64_t got, uint64_t want)
{
	if (got != want) {
		printf("FAIL %s: got 0x%016llX want 0x%016llX\n", name,
			(unsigned long long)got, (unsigned long long)want);
		failures++;
	} else {
		printf("ok   %s = 0x%016llX\n", name, (unsigned long long)got);
	}
}

static void
expect_sha256(const char *name, const uint8_t *buf, size_t len,
	const char *want_hex)
{
	uint8_t d[32];
	char got[65];
	my_sha256(buf, len, d);
	hex(d, 32, got);
	if (strcmp(got, want_hex) != 0) {
		printf("FAIL %s:\n  got  %s\n  want %s\n", name, got,
			want_hex);
		failures++;
	} else {
		printf("ok   %s\n", name);
	}
}

/* SHA-256 reference from FIPS 180-4 examples and boundary lengths. */
static void
test_sha256(void)
{
	expect_sha256("sha256 empty", (const uint8_t *)"", 0,
		"e3b0c44298fc1c149afbf4c8996fb924"
		"27ae41e4649b934ca495991b7852b855");
	expect_sha256("sha256 abc", (const uint8_t *)"abc", 3,
		"ba7816bf8f01cfea414140de5dae2223b00361"
		"a396177a9cb410ff61f20015ad");
	/* 56-byte FIPS two-block message. */
	expect_sha256("sha256 56-byte",
		(const uint8_t *)"abcdbcdecdefdefgefghfghighijhijk"
		"ijkljklmklmnlmnomnopnopq", 56,
		"248d6a61d20638b8e5c026930c3e6039a33ce459"
		"64ff2167f6ecedd419db06c1");
	/* 55 bytes: last single-block boundary before spillover. */
	static uint8_t m55[55];
	memset(m55, 'a', 55);
	expect_sha256("sha256 55xa", m55, 55,
		"9f4390f8d30c2dd92ec9f095b65e2b9ae9b0a925"
		"a5258e241c9f1e910f734318");
	/* 64 bytes: exactly one full block, padding needs a second. */
	static uint8_t m64[64];
	memset(m64, 'a', 64);
	expect_sha256("sha256 64xa", m64, 64,
		"ffe054fe7ae0cb6dc65c3af9b61d5209f439851d"
		"b43d0ba5997337df154668eb");
	/* 65 bytes: one full block plus one byte. */
	static uint8_t m65[65];
	memset(m65, 'a', 65);
	expect_sha256("sha256 65xa", m65, 65,
		"635361c48bb9e10e93e41df8378b06017c4b31a7"
		"a9a8db2e69c58eb2d1cf76ab");
	/* FIPS million-'a' vector. */
	static uint8_t mil[1000000];
	memset(mil, 'a', 1000000);
	expect_sha256("sha256 1M x a", mil, 1000000,
		"cdc76e5c9914fb9281a1c7e284d73e67f1809a48"
		"a497200e046d39ccc7112cd0");
}

static void
test_crc(void)
{
	static const uint8_t digits[] = "123456789";
	expect_u32("crc32 123456789", my_crc32(digits, 9, 0),
		UINT32_C(0xCBF43926));
	expect_u64("crc64 123456789", my_crc64(digits, 9, 0),
		UINT64_C(0x995DC9BBDF1939FA));
	expect_u32("crc32 empty", my_crc32((const uint8_t *)"", 0, 0), 0);
	expect_u64("crc64 empty", my_crc64((const uint8_t *)"", 0, 0), 0);

	/* Chaining: crc(buf, seed) must compose. */
	uint32_t c32 = my_crc32(digits, 4, 0);
	c32 = my_crc32(digits + 4, 5, c32);
	expect_u32("crc32 chained", c32, UINT32_C(0xCBF43926));
	uint64_t c64 = my_crc64(digits, 4, 0);
	c64 = my_crc64(digits + 4, 5, c64);
	expect_u64("crc64 chained", c64, UINT64_C(0x995DC9BBDF1939FA));
}

static void
test_ids(void)
{
	static const int want[16] = {
		0, 4, 4, 4, 8, 8, 8, 16, 16, 16, 32, 32, 32, 64, 64, 64
	};
	for (int i = 0; i <= CHECK_ID_MAX; i++) {
		if (check_size_by_id(i) != want[i]) {
			printf("FAIL check_size_by_id(%d) = %d want %d\n",
				i, check_size_by_id(i), want[i]);
			failures++;
		}
	}
	if (check_size_by_id(-1) != -1 || check_size_by_id(16) != -1) {
		printf("FAIL check_size_by_id out of range\n");
		failures++;
	}
	if (!check_id_supported(CHECK_ID_NONE)
		|| !check_id_supported(CHECK_ID_CRC32)
		|| !check_id_supported(CHECK_ID_CRC64)
		|| !check_id_supported(CHECK_ID_SHA256)
		|| check_id_supported(0x02)) {
		printf("FAIL check_id_supported\n");
		failures++;
	}
	printf("ok   check id tables\n");
}

static void
test_check_compute(void)
{
	static const uint8_t digits[] = "123456789";
	uint8_t out[64];

	/* CRC32 must be stored little-endian: 0xCBF43926 -> 26 39 F4 CB */
	check_compute(CHECK_ID_CRC32, digits, 9, out);
	if (out[0] != 0x26 || out[1] != 0x39 || out[2] != 0xF4
		|| out[3] != 0xCB) {
		printf("FAIL check_compute crc32 byte order: "
			"%02x %02x %02x %02x\n", out[0], out[1], out[2],
			out[3]);
		failures++;
	} else {
		printf("ok   check_compute crc32 LE\n");
	}

	/* CRC64 little-endian: 0x995DC9BBDF1939FA -> FA 39 19 DF BB C9 5D 99 */
	check_compute(CHECK_ID_CRC64, digits, 9, out);
	static const uint8_t want64[8] = {
		0xFA, 0x39, 0x19, 0xDF, 0xBB, 0xC9, 0x5D, 0x99
	};
	if (memcmp(out, want64, 8) != 0) {
		printf("FAIL check_compute crc64 byte order\n");
		failures++;
	} else {
		printf("ok   check_compute crc64 LE\n");
	}

	/* SHA-256 digest is stored as-is (big-endian words). */
	check_compute(CHECK_ID_SHA256, (const uint8_t *)"abc", 3, out);
	if (out[0] != 0xBA || out[1] != 0x78 || out[2] != 0x16
		|| out[3] != 0x8F) {
		printf("FAIL check_compute sha256 byte order\n");
		failures++;
	} else {
		printf("ok   check_compute sha256 BE digest\n");
	}
}

int
main(void)
{
	test_crc();
	test_sha256();
	test_ids();
	test_check_compute();

	if (failures) {
		printf("%d FAILURES\n", failures);
		return 1;
	}
	printf("ALL TESTS PASSED\n");
	return 0;
}

/* Print the check value of a file as hex, in the same format that
 * `xz --robot -lvv` prints it (CRCs as integers, MSB first; SHA-256
 * as raw digest bytes). Usage: mycheck crc32|crc64|sha256 FILE */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "check.h"

int
main(int argc, char **argv)
{
	if (argc != 3) {
		fprintf(stderr, "usage: %s crc32|crc64|sha256 FILE\n",
			argv[0]);
		return 2;
	}

	FILE *f = fopen(argv[2], "rb");
	if (f == NULL) {
		perror(argv[2]);
		return 2;
	}
	static uint8_t buf[16 * 1024 * 1024];
	size_t len = fread(buf, 1, sizeof(buf), f);
	if (ferror(f) || !feof(f)) {
		fprintf(stderr, "read error or file too big\n");
		return 2;
	}
	fclose(f);

	if (strcmp(argv[1], "crc32") == 0) {
		printf("%08x\n", my_crc32(buf, len, 0));
	} else if (strcmp(argv[1], "crc64") == 0) {
		printf("%016llx\n",
			(unsigned long long)my_crc64(buf, len, 0));
	} else if (strcmp(argv[1], "sha256") == 0) {
		uint8_t d[32];
		my_sha256(buf, len, d);
		for (int i = 0; i < 32; i++)
			printf("%02x", d[i]);
		printf("\n");
	} else {
		fprintf(stderr, "unknown check\n");
		return 2;
	}
	return 0;
}
